import org.reactivestreams.Publisher;
import org.reactivestreams.Subscriber;
import org.reactivestreams.Subscription;

public class CustomDataProcessor {
    public static void main(String[] args) {
        Publisher<String> publisher = s -> s.onSubscribe(new Subscription() {
            private long count = 0;
            @Override
            public void request(long n) {
                for (long i = 0; i < n && count < 3; i++) {
                    s.onNext("Event-" + (++count));
                }
                if (count >= 3) {
                    s.onComplete();
                }
            }
            @Override
            public void cancel() {
                // Cleanup resources
            }
        });

        publisher.subscribe(new Subscriber<String>() {
            private Subscription subscription;
            @Override
            public void onSubscribe(Subscription s) {
                this.subscription = s;
                s.request(2); // Request first 2 items
            }
            @Override
            public void onNext(String t) {
                System.out.println("Received: " + t);
                if (t.equals("Event-2")) {
                    subscription.request(1); // Request next item dynamically
                }
            }
            @Override
            public void onError(Throwable t) { t.printStackTrace(); }
            @Override
            public void onComplete() { System.out.println("Stream complete."); }
        });
    }
}
